Quante volte stampa `copia`? E che cosa stampa dopo?

```cpp
#include <iostream>

class Punti {
    int v;
public:
    explicit Punti(int x) : v(x) {}
    Punti(const Punti& p) : v(p.v) { std::cout << "copia\n"; }
    int get() const { return v; }
};

int somma(Punti a, Punti b) { return a.get() + b.get(); }
int doppio(const Punti& a) { return 2 * a.get(); }

int main() {
    Punti p(3);
    Punti q = p;
    std::cout << somma(p, q) << "\n";
    std::cout << doppio(p) << "\n";
    return 0;
}
```

