Nella derivata è sparito il `const` e non c'è `override`. Che cosa stampa?

```cpp
#include <iostream>

class Base {
public:
    virtual void stampa() const {
        std::cout << "Base\n";
    }
    virtual ~Base() = default;
};

class Derivata : public Base {
public:
    void stampa() {            // manca const
        std::cout << "Derivata\n";
    }
};

int main() {
    Derivata d;
    Base* p = &d;
    p->stampa();
    d.stampa();
    return 0;
}
```
